"""Triton CTC loss (_ctc_loss / ctc_loss) for the Iluvatar BI-V150 target.

Self-contained implementation of the ATen ``ctc_loss`` / ``_ctc_loss``
semantics:

  * log-domain alpha recursion, one program per batch element;
  * register-resident alpha rows with ``tl.gather`` lane shifts, so the serial
    time loop performs no global scratch round-trip and no block barrier;
  * the t-loop runs over ``[1, input_len)`` only, so variable lengths cost
    nothing extra;
  * ``zero_infinity`` and the batch reduction are fused into the device
    kernels; no framework reduction contributes to the returned value;
  * backward implements the ATen formulation
    ``dL/dlog_probs = scale * (p - posterior)`` with the same NaN placement as
    the reference;
  * ``run`` accepts both the public ``ctc_loss`` form (``reduction=...``,
    single tensor result) and the native ``_ctc_loss`` form
    (``(neg_log_likelihood, log_alpha)``).
"""

import torch
import triton
import triton.language as tl

from flag_gems.runtime import get_tuned_config

try:
    from triton.language.extra import libdevice as _ld
except Exception:  # pragma: no cover - backend without libdevice bindings
    _ld = None

_R_NONE = 0
_R_MEAN = 1
_R_SUM = 2

_INTEGRAL_DTYPES = {
    torch.uint8,
    torch.int8,
    torch.int16,
    torch.int32,
    torch.int64,
}

_STATS_CACHE = {}
_STATS_CACHE_LIMIT = 256


# ---------------------------------------------------------------------------
# small math helpers
# ---------------------------------------------------------------------------


@triton.jit
def _logf(s):
    """Natural log of a value in [1, 3] from the hardware log approximation.

    ``s`` is always ``exp(0) + exp(x1) + exp(x2)`` after the per-lane max
    subtraction, so it lies in [1, 3] and never underflows; the accurate
    libdevice polynomial (a ~26-instruction, 9-deep FMA chain) is replaced by
    the single-instruction lg2 approximation scaled by ln 2.
    """
    if _ld is not None:
        return _ld.fast_logf(s)
    return tl.log(s)


@triton.jit
def _lse3(a, b, c, use_c):
    cc = tl.where(use_c, c, -float("inf"))
    m = tl.maximum(tl.maximum(a, b), cc)
    sm = tl.where(m == -float("inf"), 0.0, m)
    s = tl.exp(a - sm) + tl.exp(b - sm) + tl.exp(cc - sm)
    return tl.where(m == -float("inf"), -float("inf"), m + _logf(s))


@triton.jit
def _lse2(a, b):
    m = tl.maximum(a, b)
    sm = tl.where(m == -float("inf"), 0.0, m)
    s = tl.exp(a - sm) + tl.exp(b - sm)
    return tl.where(m == -float("inf"), -float("inf"), m + _logf(s))


