# Bounded launch-configuration search for the forward kernel.  The warp count
# decides how the two ``tl.gather`` state shifts are lowered (warp-local
# exchange versus a shared-memory staging round trip per step) and how many
# threads share one alpha lane, so it is searched per launch geometry instead of
# being derived from one fixed rule.  ``num_warps=8`` is the previously fixed
# choice and stays in the list, so a null result cannot regress.
_FWD_CONFIGS = get_tuned_config("iluvatar_ctc_loss_candidate_0")


@triton.autotune(
    configs=_FWD_CONFIGS,
    key=["T", "C", "BLOCK_S"],
    warmup=10,
    rep=30,
)
@triton.jit
def _ctc_fwd_kernel(
    lp_ptr,
    tgt_ptr,
    ilen_ptr,
    tlen_ptr,
    out_ptr,
    raw_ptr,
    alpha_ptr,
    T,
    N,
    C,
    lp_sT,
    lp_sN,
    lp_sC,
    tgt_s1,
    tgt_stride,
    BLOCK_N: tl.constexpr,
    BLOCK_S: tl.constexpr,
    W: tl.constexpr,
    BLANK: tl.constexpr,
    TARGET_1D: tl.constexpr,
    REDUCTION: tl.constexpr,
    ZERO_INF: tl.constexpr,
    STORE_ALPHA: tl.constexpr,
    STORE_RAW: tl.constexpr,
):
    b = tl.program_id(0)
    states = tl.arange(0, BLOCK_S)

    input_len = tl.load(ilen_ptr + b).to(tl.int32)
    target_len = tl.load(tlen_ptr + b).to(tl.int32)
    state_count = target_len * 2 + 1
    valid = states < state_count
    stored = states < W

    is_blank = (states % 2) == 0
    ti = (states - 1) // 2
    tmask = (ti >= 0) & (ti < target_len)
    tsafe = tl.where(tmask, ti, 0)

    if TARGET_1D:
        nb = tl.arange(0, BLOCK_N)
        prev_lens = tl.load(tlen_ptr + nb, mask=nb < b, other=0).to(tl.int32)
        origin = tl.sum(prev_lens, 0)
    else:
        origin = b * tgt_stride

    tv = tl.load(tgt_ptr + (origin + tsafe) * tgt_s1, mask=tmask, other=BLANK)
    labels = tl.where(is_blank, BLANK, tv).to(tl.int32)

    pti = tl.where(ti > 0, ti - 1, 0)
    ptv = tl.load(
        tgt_ptr + (origin + pti) * tgt_s1,
        mask=tmask & (ti > 0),
        other=BLANK,
    )
    skip = (~is_blank) & (ti > 0) & (tv != ptv)

    lab_off = labels * lp_sC
    row = b * lp_sN

    t0 = input_len > 0
    init = (states == 0) | ((states == 1) & (target_len > 0))
    lp0 = tl.load(lp_ptr + row + lab_off, mask=init & stored & t0, other=0.0).to(
        tl.float32
    )
    alpha = tl.where(init & valid & t0, lp0, -float("inf"))
    if STORE_ALPHA:
        tl.store(alpha_ptr + b * T * W + states, alpha, mask=stored & t0)

    for t in tl.range(1, input_len):
        p1 = tl.gather(alpha, tl.maximum(states - 1, 0), 0)
        p1 = tl.where(states >= 1, p1, -float("inf"))
        p2 = tl.gather(alpha, tl.maximum(states - 2, 0), 0)
        p2 = tl.where(states >= 2, p2, -float("inf"))
        acc = _lse3(alpha, p1, p2, skip)
        lp = tl.load(lp_ptr + t * lp_sT + row + lab_off, mask=valid, other=0.0).to(
            tl.float32
        )
        alpha = tl.where(valid, acc + lp, -float("inf"))
        if STORE_ALPHA:
            tl.store(alpha_ptr + (b * T + t) * W + states, alpha, mask=stored)

    last = tl.sum(tl.where(states == state_count - 1, alpha, 0.0), 0)
    prev_idx = tl.where(target_len > 0, state_count - 2, 0)
    prev_last = tl.sum(tl.where(states == prev_idx, alpha, 0.0), 0)
    prev_last = tl.where(target_len > 0, prev_last, -float("inf"))
    loss = -_lse2(last, prev_last)
    loss = tl.where(input_len <= 0, tl.where(target_len == 0, 0.0, float("inf")), loss)

    if STORE_RAW:
        tl.store(raw_ptr + b, loss)

    if ZERO_INF:
        loss = tl.where(tl.abs(loss) == float("inf"), 0.0, loss)
    if REDUCTION == 1:
        loss = loss / (tl.maximum(target_len, 1).to(tl.float32) * N)
    tl.store(out_ptr + b, loss)


@triton.jit
def _ctc_reduce_kernel(src, out, N, BLOCK_N: tl.constexpr):
    offs = tl.arange(0, BLOCK_N)
    v = tl.load(src + offs, mask=offs < N, other=0.0)
    tl.store(out, tl.sum(v, 0))


