# backward
# ---------------------------------------------------------------------------


@triton.jit
def _ctc_init_grad_kernel(
    lp_ptr,
    ilen_ptr,
    tlen_ptr,
    nll_ptr,
    go_ptr,
    grad_ptr,
    total,
    N,
    C,
    lp_sT,
    lp_sN,
    lp_sC,
    REDUCTION: tl.constexpr,
    ZERO_INF: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < total
    b = (offs // C) % N
    t = offs // (N * C)
    c = offs % C

    input_len = tl.load(ilen_ptr + b, mask=mask, other=0).to(tl.int32)
    target_len = tl.load(tlen_ptr + b, mask=mask, other=1).to(tl.int32)
    nll = tl.load(nll_ptr + b, mask=mask, other=0.0)

    if REDUCTION == 0:
        scale = tl.load(go_ptr + b, mask=mask, other=0.0)
    else:
        scale = tl.load(go_ptr)
        if REDUCTION == 1:
            scale = scale / (tl.maximum(target_len, 1).to(tl.float32) * N)

    if ZERO_INF:
        scale = tl.where(nll == float("inf"), 0.0, scale)

    lpval = tl.load(
        lp_ptr + t * lp_sT + b * lp_sN + c * lp_sC, mask=mask, other=-float("inf")
    ).to(tl.float32)
    active = (t < input_len) & mask
    grad = tl.where(active, tl.exp(lpval) * scale, 0.0)
    grad = tl.where(
        active & (scale != 0.0) & (lpval == -float("inf")), float("nan"), grad
    )
    if not ZERO_INF:
        grad = tl.where(active & (nll == float("inf")), float("nan"), grad)
    tl.store(grad_ptr + offs, grad, mask=mask)


@triton.jit
def _ctc_bwd_kernel(
    lp_ptr,
    tgt_ptr,
    ilen_ptr,
    tlen_ptr,
    nll_ptr,
    alpha_ptr,
    go_ptr,
    grad_ptr,
    T,
    N,
    C,
    lp_sT,
    lp_sN,
    lp_sC,
    tgt_s1,
    tgt_stride,
    BLOCK_N: tl.constexpr,
    BLOCK_S: tl.constexpr,
    W: tl.constexpr,
    BLANK: tl.constexpr,
    TARGET_1D: tl.constexpr,
    REDUCTION: tl.constexpr,
    ZERO_INF: tl.constexpr,
):
    b = tl.program_id(0)
    states = tl.arange(0, BLOCK_S)

    input_len = tl.load(ilen_ptr + b).to(tl.int32)
    target_len = tl.load(tlen_ptr + b).to(tl.int32)
    nll = tl.load(nll_ptr + b)
    state_count = target_len * 2 + 1
    valid = states < state_count
    stored = states < W

    is_blank = (states % 2) == 0
    ti = (states - 1) // 2
    tmask = (ti >= 0) & (ti < target_len)
    tsafe = tl.where(tmask, ti, 0)

    if TARGET_1D:
        nb = tl.arange(0, BLOCK_N)
        prev_lens = tl.load(tlen_ptr + nb, mask=nb < b, other=0).to(tl.int32)
        origin = tl.sum(prev_lens, 0)
    else:
        origin = b * tgt_stride

    tv = tl.load(tgt_ptr + (origin + tsafe) * tgt_s1, mask=tmask, other=BLANK)
    labels = tl.where(is_blank, BLANK, tv).to(tl.int32)

    # label of state s + 1
    is_blank1 = ((states + 1) % 2) == 0
    ti1 = states // 2
    tmask1 = (ti1 >= 0) & (ti1 < target_len)
    ti1s = tl.where(tmask1, ti1, 0)
    tv1 = tl.load(tgt_ptr + (origin + ti1s) * tgt_s1, mask=tmask1, other=BLANK)
    labels1 = tl.where(is_blank1, BLANK, tv1).to(tl.int32)

    # label of state s + 2
    ti2 = (states + 1) // 2
    tmask2 = (ti2 >= 0) & (ti2 < target_len)
    ti2s = tl.where(tmask2, ti2, 0)
    tv2 = tl.load(tgt_ptr + (origin + ti2s) * tgt_s1, mask=tmask2, other=BLANK)
    labels2 = tv2.to(tl.int32)

    skip = (~is_blank) & (states + 2 < state_count) & (tv != tv2)
    n1_ok = (states + 1) < state_count

    if REDUCTION == 0:
        scale = tl.load(go_ptr + b)
    else:
        scale = tl.load(go_ptr)
        if REDUCTION == 1:
            scale = scale / (tl.maximum(target_len, 1).to(tl.float32) * N)

    if ZERO_INF:
        scale = tl.where(nll == float("inf"), 0.0, scale)

    beta = tl.where(
        ((states == state_count - 1) | ((states == state_count - 2) & (target_len > 0)))
        & valid
        & (input_len > 0),
        0.0,
        -float("inf"),
    )
    log_likelihood = tl.where(scale != 0.0, -nll, 0.0)
    post_on = valid & (scale != 0.0)
    row = b * lp_sN
    gbase = b * C

    for step in tl.range(0, input_len):
        t = input_len - 1 - step
        alpha_t = tl.load(
            alpha_ptr + (b * T + t) * W + states, mask=stored, other=-float("inf")
        ).to(tl.float32)
        posterior = tl.where(post_on, tl.exp(alpha_t + beta - log_likelihood), 0.0)
        tl.atomic_add(
            grad_ptr + t * (N * C) + gbase + labels,
            -scale * posterior,
            sem="relaxed",
            mask=post_on,
        )

        lp_c = tl.load(
            lp_ptr + t * lp_sT + row + labels * lp_sC, mask=valid, other=-float("inf")
        ).to(tl.float32)
        lp_1 = tl.load(
            lp_ptr + t * lp_sT + row + labels1 * lp_sC, mask=n1_ok, other=-float("inf")
        ).to(tl.float32)
        lp_2 = tl.load(
            lp_ptr + t * lp_sT + row + labels2 * lp_sC, mask=skip, other=-float("inf")
        ).to(tl.float32)

        b1 = tl.gather(beta, tl.minimum(states + 1, BLOCK_S - 1), 0)
        b2 = tl.gather(beta, tl.minimum(states + 2, BLOCK_S - 1), 0)
        n1 = tl.where(n1_ok, b1, -float("inf")) + lp_1
        n2 = tl.where(skip, b2, -float("inf")) + lp_2
        beta = _lse3(beta + lp_c, n1, n2, skip)


@triton.jit
def _cast_kernel(src, dst, total, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < total
    v = tl.load(src + offs, mask=mask)
    tl.store(dst + offs, v, mask=mask)


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------


def _reduction_enum(reduction):
    if isinstance(reduction, str):
        if reduction == "none":
            return _R_NONE
        if reduction == "mean":
            return _R_MEAN
        if reduction == "sum":
            return _R_SUM
        raise ValueError(
            "ctc_loss expected reduction to be one of 'none', 'mean', or 'sum', "
            f"but got {reduction!r}"
        )
    return int(reduction)


def _is_integral_dtype(dtype):
    return dtype in _INTEGRAL_DTYPES


def _lengths_to_tensor(lengths, device, name):
    if torch.is_tensor(lengths):
        if lengths.dtype not in _INTEGRAL_DTYPES:
            raise RuntimeError(f"{name} must be integral")
        if lengths.dtype is not torch.long:
            lengths = lengths.to(dtype=torch.long)
        if lengths.device != device:
            lengths = lengths.to(device=device)
        if lengths.ndim != 1 or not lengths.is_contiguous():
            lengths = (
                lengths.reshape(1)
                if lengths.ndim == 0
                else lengths.reshape(-1).contiguous()
            )
        return lengths
    out = torch.tensor(lengths, device=device)
    if out.dtype not in _INTEGRAL_DTYPES:
        raise RuntimeError(f"{name} must be integral")
    if out.dtype is not torch.long:
        out = out.to(dtype=torch.long)
    return out.reshape(1) if out.ndim == 0 else out.reshape(-1).contiguous()


def _lengths_stats_device(lengths):
    """(min, max, sum) of one length tensor, cached per (storage, version).

    The cached tensor reference keeps the storage alive, so a later tensor can
    never occupy the same address with a stale version counter.
    """
    key = (lengths.device, lengths.data_ptr(), lengths.numel(), lengths._version)
    entry = _STATS_CACHE.get(key)
    if entry is not None:
        return entry[1]
    stats_tensor = torch.stack((lengths.min(), lengths.max(), lengths.sum())).cpu()
    stats = tuple(int(value) for value in stats_tensor.tolist())
    if len(_STATS_CACHE) >= _STATS_CACHE_LIMIT:
        _STATS_CACHE.clear()
    _STATS_CACHE[key] = (lengths, stats)
    return stats


def _lengths_stats_host(lengths):
    values = [int(v) for v in lengths]
    if not values:
        return 0, 0, 0
    return min(values), max(values), sum(values)


def _num_warps(block_s):
    n = block_s // 32
    if n < 1:
        return 1
    if n > 8:
        return 8
    return n


class _CtcSetup:
    """Normalized inputs shared by the forward and backward wrappers."""

    __slots__ = (
        "alpha_dtype",
        "blank",
        "block_n",
        "block_s",
        "device",
        "geom",
        "il_ref",
        "input_lengths",
        "lil",
        "lp_ref",
        "lt",
        "num_warps",
        "orig_dtype",
        "state_count_max",
        "sT",
        "sN",
        "sC",
        "T",
        "N",
        "C",
        "target_1d",
        "target_lengths",
        "target_stride",
        "targets",
        "tensor_lengths",
        "tg_ref",
        "tgt_s1",
        "tl_ref",
        "unbatched",
        "vers",
    )


_LAST_SETUP = None


def _prepare(log_probs, targets, input_lengths, target_lengths, blank):
    """Normalised launch state, reusing the previous one when nothing changed.

    The reuse guard is the exact identity of every argument plus the layout, the
    in-place version counters (tensor lengths) or the exact values (python list
    lengths), and the cached setup keeps references to the inputs so an object
    identity can never be recycled underneath it.  Anything that could alter
    validation or launch geometry therefore forces a full re-validation.  Mixed
    tensor/list lengths are never cached.
    """
    global _LAST_SETUP
    st = _LAST_SETUP
    if st is not None and st.blank == blank and st.lp_ref is log_probs:
        if st.tg_ref is targets and st.geom == (
            log_probs.shape,
            log_probs.stride(),
            log_probs.dtype,
            targets.shape,
            targets.stride(),
            targets.dtype,
        ):
            if st.tensor_lengths:
                if (
                    st.il_ref is input_lengths
                    and st.tl_ref is target_lengths
                    and st.vers
                    == (
                        input_lengths._version,
                        input_lengths.data_ptr(),
                        target_lengths._version,
                        target_lengths.data_ptr(),
                        targets._version,
                    )
                ):
                    return st
            elif (
                not torch.is_tensor(input_lengths)
                and st.vers == (targets._version,)
                and st.lil == tuple(input_lengths)
                and st.lt == tuple(target_lengths)
            ):
                return st
    st = _prepare_uncached(log_probs, targets, input_lengths, target_lengths, blank)
    st.lp_ref = log_probs
    st.tg_ref = targets
    st.il_ref = input_lengths
    st.tl_ref = target_lengths
    st.geom = (
        log_probs.shape,
        log_probs.stride(),
        log_probs.dtype,
        targets.shape,
        targets.stride(),
        targets.dtype,
    )
    both = torch.is_tensor(input_lengths) and torch.is_tensor(target_lengths)
    neither = not torch.is_tensor(input_lengths) and not torch.is_tensor(target_lengths)
    if both:
        st.tensor_lengths = True
        st.lil = None
        st.lt = None
        st.vers = (
            input_lengths._version,
            input_lengths.data_ptr(),
            target_lengths._version,
            target_lengths.data_ptr(),
            targets._version,
        )
        _LAST_SETUP = st
    elif neither:
        st.tensor_lengths = False
        st.lil = tuple(input_lengths)
        st.lt = tuple(target_lengths)
        st.vers = (targets._version,)
        _LAST_SETUP = st
    else:
        _LAST_SETUP = None
    return st


def _prepare_uncached(log_probs, targets, input_lengths, target_lengths, blank):
    if log_probs.ndim not in (2, 3):
        raise RuntimeError(
            "ctc_loss expects log_probs to be a 2D or 3D tensor, "
            f"but got {log_probs.ndim}D"
        )
    if not torch.is_floating_point(log_probs):
        raise RuntimeError(f'"ctc_loss" not implemented for {log_probs.dtype}')
    if blank < 0 or blank >= log_probs.shape[-1]:
        raise RuntimeError("blank must be in label range")

    st = _CtcSetup()
    st.blank = int(blank)
    st.orig_dtype = log_probs.dtype
    st.alpha_dtype = (
        log_probs.dtype
        if log_probs.dtype in (torch.float32, torch.float64)
        else torch.float32
    )
    st.device = log_probs.device
    st.unbatched = log_probs.ndim == 2
    if st.unbatched:
        st.T, st.C = log_probs.shape
        st.N = 1
        st.sT, st.sC = log_probs.stride()
        st.sN = 0
    else:
        st.T, st.N, st.C = log_probs.shape
        st.sT, st.sN, st.sC = log_probs.stride()

    if torch.is_floating_point(targets):
        work_targets = targets.to(dtype=torch.long)
    elif _is_integral_dtype(targets.dtype):
        work_targets = targets
    else:
        raise RuntimeError("ctc_loss targets must be integral or floating point")

    list_input_lengths = not torch.is_tensor(input_lengths)
    list_target_lengths = not torch.is_tensor(target_lengths)
    work_input_lengths = _lengths_to_tensor(input_lengths, st.device, "input_lengths")
    work_target_lengths = _lengths_to_tensor(
        target_lengths, st.device, "target_lengths"
    )

    if work_input_lengths.numel() != st.N:
        raise RuntimeError(
            f"ctc_loss expected input_lengths to have size {st.N}, "
            f"but got {work_input_lengths.numel()}"
        )
    if work_target_lengths.numel() != st.N:
        raise RuntimeError(
            f"ctc_loss expected target_lengths to have size {st.N}, "
            f"but got {work_target_lengths.numel()}"
        )

    if list_input_lengths:
        min_input_length, max_input_length, _ = _lengths_stats_host(input_lengths)
    else:
        min_input_length, max_input_length, _ = _lengths_stats_device(
            work_input_lengths
        )
    if list_target_lengths:
        min_target_length, max_target, total_target_length = _lengths_stats_host(
            target_lengths
        )
    else:
        (
            min_target_length,
            max_target,
            total_target_length,
        ) = _lengths_stats_device(work_target_lengths)

    if min_input_length < 0 or max_input_length > st.T:
        raise RuntimeError("ctc_loss input_lengths must be in [0, T]")
    if min_target_length < 0:
        raise RuntimeError("ctc_loss target_lengths must be non-negative")

    st.state_count_max = 2 * max_target + 1
    if work_targets.ndim == 1:
        st.target_1d = True
        if total_target_length != work_targets.numel():
            raise RuntimeError(
                "ctc_loss expected concatenated targets length to equal "
                "sum(target_lengths)"
            )
        st.target_stride = 0
        st.tgt_s1 = int(work_targets.stride(0)) if work_targets.numel() else 1
    elif work_targets.ndim == 2:
        st.target_1d = False
        if max_target > work_targets.shape[1]:
            raise RuntimeError(
                "ctc_loss target_lengths cannot exceed padded target width"
            )
        st.target_stride = int(work_targets.stride(0))
        st.tgt_s1 = int(work_targets.stride(1))
    else:
        raise RuntimeError(
            "ctc_loss expects targets to be a 1D concatenated tensor or a "
            f"2D padded tensor, but got {work_targets.ndim}D"
        )

    st.targets = work_targets
    st.input_lengths = work_input_lengths
    st.target_lengths = work_target_lengths
    st.block_s = max(2, triton.next_power_of_2(st.state_count_max))
    st.block_n = max(2, triton.next_power_of_2(st.N))
    st.num_warps = _num_warps(st.block_s)
    return st


def _launch_forward(st, log_probs, reduction, zero_infinity, store_alpha, store_raw):
    """Run the alpha recursion; returns (user_output, raw_nll, log_alpha)."""
    red = reduction
    if red == _R_NONE:
        out = torch.empty((st.N,), dtype=st.orig_dtype, device=st.device)
        out_arg = out
    else:
        out_arg = torch.empty((st.N,), dtype=torch.float32, device=st.device)

    if store_raw:
        raw = torch.empty((st.N,), dtype=torch.float32, device=st.device)
    else:
        raw = None
    if store_alpha:
        log_alpha = torch.empty(
            (st.N, st.T, st.state_count_max), dtype=st.alpha_dtype, device=st.device
        )
    else:
        log_alpha = None

    _ctc_fwd_kernel[(st.N,)](
        log_probs,
        st.targets,
        st.input_lengths,
        st.target_lengths,
        out_arg,
        raw if store_raw else out_arg,
        log_alpha if store_alpha else out_arg,
        st.T,
        st.N,
        st.C,
        st.sT,
        st.sN,
        st.sC,
        st.tgt_s1,
        st.target_stride,
        BLOCK_N=st.block_n,
        BLOCK_S=st.block_s,
        W=st.state_count_max,
        BLANK=st.blank,
        TARGET_1D=st.target_1d,
        REDUCTION=red,
        ZERO_INF=bool(zero_infinity),
        STORE_ALPHA=store_alpha,
        STORE_RAW=store_raw,
    )

    if red == _R_NONE:
        output = out
        if st.unbatched:
            output = output.squeeze(0)
    else:
        output = torch.empty((), dtype=st.orig_dtype, device=st.device)
        _ctc_reduce_kernel[(1,)](out_arg, output, st.N, BLOCK_N=st.block_n, num_warps=1)
    return output, raw, log_alpha


def _to_dtype(src, total, dtype, device):
    if dtype == torch.float32 or total == 0:
        return src
    dst = torch.empty(src.shape, dtype=dtype, device=device)
    block = 256
    _cast_kernel[(triton.cdiv(total, block),)](
        src, dst, total, BLOCK=block, num_warps=4
    )
    return dst


class CtcLossFunction(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx,
        log_probs,
        targets,
        input_lengths,
        target_lengths,
        blank,
        reduction,
        zero_infinity,
        store_alpha,
        native,
    ):
        red = _reduction_enum(reduction)
        if red not in (_R_NONE, _R_MEAN, _R_SUM):
            raise ValueError(f"ctc_loss got invalid reduction enum {red}")

        st = _prepare(log_probs, targets, input_lengths, target_lengths, blank)
        needs_grad = ctx.needs_input_grad[0]
        keep_alpha = bool(store_alpha) or needs_grad

        output, raw, log_alpha = _launch_forward(
            st, log_probs, red, zero_infinity, keep_alpha, needs_grad
        )

        if keep_alpha:
            if log_alpha.dtype == st.orig_dtype:
                alpha_out = log_alpha
            else:
                alpha_out = _to_dtype(
                    log_alpha,
                    st.N * st.T * st.state_count_max,
                    st.orig_dtype,
                    st.device,
                )
            if st.unbatched:
                alpha_out = alpha_out.squeeze(0)
        else:
            alpha_out = torch.empty((0,), dtype=st.orig_dtype, device=st.device)

        if needs_grad:
            ctx.save_for_backward(
                log_probs,
                st.targets,
                st.input_lengths,
                st.target_lengths,
                raw,
                log_alpha,
            )
            ctx.meta = (
                st.T,
                st.N,
                st.C,
                st.sT,
                st.sN,
                st.sC,
                st.tgt_s1,
                st.target_stride,
                st.blank,
                red,
                bool(zero_infinity),
                st.unbatched,
                st.orig_dtype,
                st.block_s,
                st.block_n,
                st.num_warps,
                st.state_count_max,
                st.target_1d,
            )

        return output, alpha_out

    @staticmethod
    def backward(ctx, grad_output, grad_alpha):
        (
            log_probs,
            work_targets,
            work_input_lengths,
            work_target_lengths,
            nll,
            log_alpha,
        ) = ctx.saved_tensors
        (
            T,
            N,
            C,
            sT,
            sN,
            sC,
            tgt_s1,
            target_stride,
            blank,
            red,
            zero_infinity,
            unbatched,
            orig_dtype,
            block_s,
            block_n,
            num_warps,
            state_count_max,
            target_1d,
        ) = ctx.meta
        device = log_probs.device

        grad_f32 = torch.empty((T, N, C), dtype=torch.float32, device=device)
        total = T * N * C
        if total > 0:
            block = 256
            _ctc_init_grad_kernel[(triton.cdiv(total, block),)](
                log_probs,
                work_input_lengths,
                work_target_lengths,
                nll,
                grad_output,
                grad_f32,
                total,
                N,
                C,
                sT,
                sN,
                sC,
                REDUCTION=red,
                ZERO_INF=zero_infinity,
                BLOCK=block,
                num_warps=4,
            )
            if N > 0 and state_count_max > 0:
                _ctc_bwd_kernel[(N,)](
                    log_probs,
                    work_targets,
                    work_input_lengths,
                    work_target_lengths,
                    nll,
                    log_alpha,
                    grad_output,
                    grad_f32,
                    T,
                    N,
                    C,
                    sT,
                    sN,
                    sC,
                    tgt_s1,
                    target_stride,
                    BLOCK_N=block_n,
                    BLOCK_S=block_s,
                    W=state_count_max,
                    BLANK=blank,
                    TARGET_1D=target_1d,
                    REDUCTION=red,
                    ZERO_INF=zero_infinity,
                    num_warps=num_warps,
                )

        grad = _to_dtype(grad_f32, total, orig_dtype, device)
        if unbatched:
            grad = grad.squeeze(1)
        return grad, None, None, None, None, None, None, None, None


def _forward_direct(
    log_probs,
    targets,
    input_lengths,
    target_lengths,
    blank,
    red,
    zero_infinity,
    want_alpha,
):
    """Forward without autograd bookkeeping (nothing enters the autograd graph)."""
    st = _prepare(log_probs, targets, input_lengths, target_lengths, blank)
    output, _raw, log_alpha = _launch_forward(
        st, log_probs, red, zero_infinity, bool(want_alpha), False
    )
    if want_alpha:
        if log_alpha.dtype != st.orig_dtype:
            log_alpha = _to_dtype(
                log_alpha,
                st.N * st.T * st.state_count_max,
                st.orig_dtype,
                st.device,
            )
        if st.unbatched:
            log_alpha = log_alpha.squeeze(0)
    else:
        log_alpha = None
    return output, log_alpha


def _ctc_loss(
    log_probs,
    targets,
    input_lengths,
    target_lengths,
    blank=0,
    reduction=None,
    zero_infinity=False,
):
    """CTC loss with both public call forms.

    ``reduction`` selects the public ``ctc_loss`` form and returns a single
    tensor.  When ``reduction`` is omitted (or a bool is supplied in its
    place, matching the native positional ``zero_infinity`` slot) the native
    ``_ctc_loss`` form is used and ``(neg_log_likelihood, log_alpha)`` is
    returned.
    """
    native = reduction is None or isinstance(reduction, bool)
    if native:
        if isinstance(reduction, bool):
            zero_infinity = reduction
        red = _R_NONE
        # Native aten::_ctc_loss returns the raw negative log-likelihood: the
        # zero_infinity rewrite is applied by the higher-level ctc_loss wrapper.
        zero_inf = False
    else:
        red = _reduction_enum(reduction)
        if red not in (_R_NONE, _R_MEAN, _R_SUM):
            raise ValueError(f"ctc_loss got invalid reduction enum {red}")
        zero_inf = bool(zero_infinity)

    if torch.is_grad_enabled() and log_probs.requires_grad:
        out = CtcLossFunction.apply(
            log_probs,
            targets,
            input_lengths,
            target_lengths,
            int(blank),
            red,
            zero_inf,
            native,
            native,
        )
        return out if native else out[0]

    out, alpha = _forward_direct(
        log_probs,
        targets,
        input_lengths,
        target_lengths,
        int(blank),
        red,
        zero_inf,
        native,
    )
    return (out, alpha) if native else out


ctc_loss = _ctc_loss
